const getJwtTccProxy = once(()=>{
    const isPreview = checkTccProxyFlag('preview', 'jwt-config');
    const isTest = checkTccProxyFlag('test', 'jwt-config');
    const instance = new TccProxy({
        namespace: 'bytecloud.fe.config',
        key: 'jwt',
        isPreview,
        isTest,
        defaultValue: defaultJwtConfig,
        hostname: 'undefined' != typeof location ? location.hostname : '',
        fetchStrategy: 'networkFirst',
        validator (value) {
            try {
                return Object.prototype.hasOwnProperty.call(value, 'jwtItems');
            } catch (error) {
                return false;
            }
        },
        useFallbackHostname: true
    });
    return {
        instance,
        isProd: !isPreview && !isTest
    };
});
